// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz the caller and the to-array length indicator (we pass an array constructed from the length)
    // The deciding parameter is uint256 len which the fuzzer will choose; we construct an address[] of that length.
    function testFuzz_property(address from, address caddress, uint256 len) public {
        // Keep len within a reasonable bound to avoid OOG in test environment but allow zero
        len = bound(len, 0, 8);

        // build the _tos array of length `len`. Use harmless recipient addresses (can be zero or any).
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // fill with caddress so calls target a contract (but caddress here is an arbitrary EOA from fuzzing);
            // we don't need the calls to succeed for this property because we're only checking behavior when len==0.
            tos[i] = address(0x1234);
        }

        // We only need to observe whether call reverts when tos.length == 0.
        bool ok;
        try c.transfer(from, caddress, tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for ALL inputs, the correct contract reverts when tos.length == 0.
        // Therefore if len == 0, ok must be false on the reference. The mutant that removed the guard
        // will return true (ok == true) for some inputs (len == 0), causing this assertion to fail.
        if (len == 0) {
            assertTrue(!ok);
        } else {
            // for len > 0 we cannot deterministically assert success because external calls may fail,
            // so we do not assert anything in that branch. Still, the universal property is covered by len==0.
            assertTrue(true);
        }
    }
}
